import java.io.BufferedReader;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        try (FileWriter w = new FileWriter("{name}")) {
            w.write("1|{a}|{s}\n");
        }
        try (BufferedReader r = new BufferedReader(new FileReader("{name}"))) {
            String hang = r.readLine();
            int cut = hang.indexOf("|");
            String rest = hang.substring(cut + 1);
            int cut2 = rest.indexOf("|");
            String fenshu = rest.substring(0, cut2);
            String mingzi = rest.substring(cut2 + 1);
            int score = Integer.parseInt(fenshu);
            System.out.println("名字：" + mingzi);
            System.out.println("分数：" + score);
            System.out.println("加一分就是：" + (score + 1));
        }
    }
}

